fn main() -> Int {
  let contacts: Map[Str,Str] = Map[Str,Str].new();
  let names: Vec[Str] = Vec[Str].new();

  contacts.insert("Eve", "555-0300");
  names.push("Eve");

  contacts.insert("Dan", "555-0400");
  names.push("Dan");

  match contacts.get("Eve") {
    Some(phone) -> io.println("Eve: " + phone);
    None -> io.println("Not found");
  }

  io.println("All contacts:");
  for name in names {
    match contacts.get(name) {
      Some(phone) -> io.println("  " + name + ": " + phone);
      None -> {}
    }
  }

  io.println("Total: " + string.int_to_str(names.len()));
  return 0;
}
